import Foundation

/// Literal input/expected pairs transcribed from the user's Sample Recipe Data.txt.
/// Only SAMPLE/this/Should be framing and outer blank separator rows are removed.
/// Expected files are independent user examples, never generated by the transform.
enum UserRecipeFixtures {
    static let directory = TestPaths.fixtures
    static func pair(_ number: Int) throws -> (String, String) {
        (
            try String(
                contentsOf: directory.appendingPathComponent("recipe-user-sample\(number)-input.txt"), encoding: .utf8),
            try String(
                contentsOf: directory.appendingPathComponent("recipe-user-sample\(number)-expected.txt"),
                encoding: .utf8)
        )
    }
    /// G377: the rules written for these four samples are test data, not part of the app. The
    /// rule file is the bundled recipe template plus the literal headings and note suffixes
    /// that only these samples contain.
    static func sampleRules() throws -> AutomationRuleSet {
        try AutomationRuleSet.decode(
            Data(contentsOf: directory.appendingPathComponent("recipe-user-samples.rules.json")))
    }
    /// An explicit user-configurable recipe for these supplied examples. This
    /// deliberately promises no inference about arbitrary headings or notes.
    static func configured() throws -> AutomationDefinition {
        var value = AutomationDefinition.example
        value.name = "My ingredient cleanup"
        value.steps = try sampleRules().steps
        return value
    }
}

@main struct UserRecipeChecks {
    static func main() {
        Checks.run("UserRecipeChecks") {
            let definition = try UserRecipeFixtures.configured()
            try definition.validate()
            // G377: the shipped template is the same pipeline without the sample-specific literals.
            let template = try AutomationTemplates.load("recipe-ingredient-cleanup")
            let literalKinds: Set<AutomationDefinition.Step.Kind> = [.clearLinesEqualTo, .replaceLiteral]
            check(
                definition.steps.filter { !literalKinds.contains($0.kind) } == template.steps,
                "the sample rule file is the bundled recipe template plus literal rules only")
            fixtureCheck(
                definition.steps.filter { literalKinds.contains($0.kind) }.count == 8,
                "the sample rule file carries the eight sample-specific literal rules")
            check(
                !template.steps.contains { literalKinds.contains($0.kind) },
                "the bundled recipe template carries no sample-specific literal text")
            var generic = definition
            generic.steps = template.steps
            check(
                try generic.transform("Sauce:\n- **2 eggs** (Note 1)\n\nYellow Rice\n▢ 1 cup rice , (optional)\n")
                    == "2 eggs\nYellow Rice\n1 cup rice , (optional)\n",
                "the bundled recipe template cleans markers and notes and leaves unknown headings and notes alone")
            for (index, rows) in [32, 7, 13, 13].enumerated() {
                let number = index + 1, (input, expected) = try UserRecipeFixtures.pair(number)
                fixtureCheck(
                    expected.split(separator: "\n").count == rows,
                    "sample \(number) independently supplied expected \(rows) ingredient rows")
                let output = try definition.transform(input)
                check(output.utf8.elementsEqual(expected.utf8), "sample \(number) exact user expected bytes")
                check(
                    try definition.transform(output).utf8.elementsEqual(expected.utf8),
                    "sample \(number) cleanup idempotent")
                var renamed = definition
                renamed.name = "Scott's chosen label"
                check(
                    try renamed.transform(input).utf8.elementsEqual(expected.utf8),
                    "sample \(number) configurable name does not affect behavior")
            }
            // G380: each input has its own stored expected bytes; nothing is adjusted at run time.
            for (inputName, expectedName) in [
                ("recipe-markdown-input.txt", "recipe-cleaned-expected.txt"),
                ("recipe-browser-plain-input.txt", "recipe-browser-cleaned-expected.txt"),
                ("recipe-plain-copy-derived.txt", "recipe-plain-copy-expected.txt")
            ] {
                let input = try String(
                    contentsOf: UserRecipeFixtures.directory.appendingPathComponent(inputName), encoding: .utf8)
                let expected = try String(
                    contentsOf: UserRecipeFixtures.directory.appendingPathComponent(expectedName), encoding: .utf8)
                check(
                    try definition.transform(input).utf8.elementsEqual(expected.utf8),
                    "prior confirmed cleanup exact compatibility: \(inputName)")
            }
            check(
                try definition.transform("Ingredients\nCups\nMetric\nGarnish (optional)\nSauce:\n2 eggs (optional)\n")
                    == "2 eggs (optional)\n",
                "configured structural headings removed without blanket parenthetical stripping")
            // G380: behaviour on text that is none of the four samples. The byte-exact sample pairs
            // above are regression anchors only, because the preset's rules were written from them.
            check(
                try definition.transform("Dressing\n2 eggs\n") == "Dressing\n2 eggs\n",
                "an unknown heading without a colon is kept, not guessed at")
            check(
                try definition.transform("For the sauce:\n2 eggs\n") == "2 eggs\n",
                "an unmarked letter-leading line that ends in a colon is cleared")
            check(
                try definition.transform("2 cups stock:\n1 egg\n") == "2 cups stock:\n1 egg\n",
                "a digit-leading line that ends in a colon is kept as an ingredient")
            check(
                try definition.transform("1 can (14 oz) tomatoes\n3 (6-inch) tortillas\n")
                    == "1 can (14 oz) tomatoes\n3 (6-inch) tortillas\n", "parenthetical quantities are kept")
            check(
                try definition.transform("Sauce: 2 tbsp soy\n") == "Sauce: 2 tbsp soy\n",
                "a colon in the middle of a line does not make it a heading")
            let (_, first) = try UserRecipeFixtures.pair(1)
            fixtureCheck(
                first.components(separatedBy: "1/2 teaspoon black pepper").count == 3,
                "duplicate ingredient rows preserved")
            let (_, third) = try UserRecipeFixtures.pair(3)
            fixtureCheck(
                third.contains("½ teaspoon kosher salt") && third.contains("⅛ teaspoon ground nutmeg")
                    && third.contains("won’t"), "Unicode fractions and punctuation unchanged")
            let (_, fourth) = try UserRecipeFixtures.pair(4)
            fixtureCheck(
                fourth.hasPrefix("2 large chicken breasts\n") && fourth.contains("2 tbps Dijon mustard"),
                "unmarked first ingredient retained and user's spelling preserved")
            check(
                definition.input == .document && definition.output == .editor && definition.previewBeforeApply == false,
                "cleanup remains direct current-document action")
            check(
                AutomationDefinition.remindersExample.output == .reminders
                    && AutomationDefinition.remindersExample.id != definition.id,
                "Reminders remains separate explicit action")
            Checks.summary { "PASS UserRecipeChecks: \(Checks.count) assertions" }
        }
    }
}
